import org.apache.commons.math3.util.ArithmeticUtils;

public class MCM {
  public static void main(String[] args) {
      int[] arr = {3, 6, 9};

      // En Java Commons Math se usa LCM, pero no soporta Arrays (Reducción).
      // El programador debe calcular recursivamente en un bucle:
      int mcm_actual = arr[0];
      for (int i = 1; i < arr.length; i++) {
          mcm_actual = ArithmeticUtils.lcm(mcm_actual, arr[i]);
      }

      System.out.println(mcm_actual);
  }
}
